import { DigoAsset } from '@digo-org/digo-api';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, Box } from '@react-three/drei';

export class Asset extends DigoAsset {
  constructor() {
    super();
  }

  override render() {
    const size = this.globalParameters['cube-size'] as number || 2;
    const color = this.globalParameters['cube-color'] as string || '#ff6b6b';
    const rotationSpeed = this.globalParameters['rotation-speed'] as number || 1;
    const positionX = this.globalParameters['position-x'] as number || 0;
    const positionY = this.globalParameters['position-y'] as number || 0;
    const positionZ = this.globalParameters['position-z'] as number || 0;
    const backgroundColor = this.globalParameters['background-color'] as string || '#1a1a1a';
    const showGrid = this.globalParameters['show-grid'] as boolean || false;

    return (
      <div style={{ width: '100%', height: '100%', background: backgroundColor }}>
        <Canvas camera={{ position: [5, 5, 5], fov: 50 }}>
          <ambientLight intensity={0.5} />
          <directionalLight position={[10, 10, 5]} intensity={1} />
          <pointLight position={[-10, -10, -5]} intensity={0.5} />

          <Box
            args={[size, size, size]}
            position={[positionX, positionY, positionZ]}
          >
            <meshStandardMaterial color={color} />
          </Box>

          {showGrid && <gridHelper args={[10, 10]} />}

          <OrbitControls enableDamping dampingFactor={0.05} />
        </Canvas>
      </div>
    );
  }
}

